import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Webcam from "react-webcam";
import {
  getAuth,
  RecaptchaVerifier,
  signInWithPhoneNumber,
} from "firebase/auth";
import axios from "axios";
import "./Login.css";
import app from "../../firebase";

const auth = getAuth(app);

const Login = () => {
  const navigate = useNavigate();
  const [step, setStep] = useState(1); // 1: Basic info, 2: Email verification, 3: Phone verification, 4: Biometric
  const [name, setName] = useState("");
  const [aadhaarNumber, setAadhaarNumber] = useState("");
  const [voterId, setVoterId] = useState("");
  const [email, setEmail] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [emailOtp, setEmailOtp] = useState("");
  const [phoneOtp, setPhoneOtp] = useState("");
  const [emailOtpSent, setEmailOtpSent] = useState(false);
  const [phoneOtpSent, setPhoneOtpSent] = useState(false);
  const [emailVerificationSuccess, setEmailVerificationSuccess] =
    useState(false);
  const [phoneVerificationSuccess, setPhoneVerificationSuccess] =
    useState(false);
  const [confirmationResult, setConfirmationResult] = useState(null);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);
  const [showWebcam, setShowWebcam] = useState(false);
  const [verificationSuccess, setVerificationSuccess] = useState(false);
  const [captureSuccess, setCaptureSuccess] = useState(false);
  const [fingerprintImage, setFingerprintImage] = useState(null);
  const [generatedEmailOtp, setGeneratedEmailOtp] = useState("");
  const webcamRef = React.useRef(null);

  React.useEffect(() => {
    return () => {
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }
    };
  }, []);

  const reCaptchverify = () => {
    if (!window.recaptchaVerifier) {
      window.recaptchaVerifier = new RecaptchaVerifier(
        auth,
        "recaptcha-container",
        {
          size: "normal",
          callback: (response) => {
            console.log("reCAPTCHA solved", response);
          },
          "expired-callback": () => {
            console.log("reCAPTCHA expired");
            window.recaptchaVerifier.render().then((widgetId) => {
              window.recaptchaWidgetId = widgetId;
            });
          },
        }
      );
    }
    return window.recaptchaVerifier;
  };

  const verifyPhoneCode = () => {
    if (!confirmationResult) {
      setError("No confirmation result available");
      return Promise.reject("No confirmation result");
    }
    return confirmationResult.confirm(phoneOtp);
  };

  const validateBasicInfo = () => {
    if (!name.trim()) {
      setError("Please enter your name as per Aadhaar");
      return false;
    }
    if (!aadhaarNumber || aadhaarNumber.length !== 12) {
      setError("Please enter a valid 12-digit Aadhaar number");
      return false;
    }
    if (!voterId.trim()) {
      setError("Please enter your Voter ID");
      return false;
    }
    if (!email.trim() || !/\S+@\S+\.\S+/.test(email)) {
      setError("Please enter a valid email address");
      return false;
    }
    return true;
  };

  const validatePhoneInfo = () => {
    if (!phoneNumber || phoneNumber.length !== 10) {
      setError("Please enter a valid 10-digit phone number");
      return false;
    }
    return true;
  };

  const sendEmailOTP = async () => {
    setError("");
    if (!validateBasicInfo()) return;

    setLoading(true);
    try {
      const response = await axios.post(
        "http://localhost:5000/api/send-email-otp",
        {
          email,
          voterId,
        }
      );

      if (response.data.success) {
        setGeneratedEmailOtp(response.data.otp);
        setEmailOtpSent(true);
        setError("");
        console.log("Email OTP sent successfully");
      }
    } catch (error) {
      console.error("Email OTP sending error:", error);
      setError(
        `Failed to send email OTP: ${
          error.response?.data?.message || error.message
        }`
      );
    } finally {
      setLoading(false);
    }
  };

  const verifyEmailOTP = async () => {
    setError("");
    if (!emailOtp || emailOtp.length !== 6) {
      setError("Please enter a valid 6-digit OTP");
      return;
    }

    setLoading(true);
    try {
      const response = await axios.post(
        "http://localhost:5000/api/verify-email-otp",
        {
          email,
          voterId,
          otp: generatedEmailOtp,
          submittedOTP: emailOtp,
        }
      );

      if (response.data.success) {
        setEmailVerificationSuccess(true);
        setStep(3);
        setError("");
      }
    } catch (error) {
      setError("Invalid email OTP. Please try again.");
      console.error("Email OTP verification error:", error);
    } finally {
      setLoading(false);
    }
  };

  const sendPhoneOTP = async () => {
    setError("");
    if (!validatePhoneInfo()) return;

    setLoading(true);
    try {
      const verifier = reCaptchverify();
      const formattedPhone = `+91${phoneNumber}`;

      await verifier.render();
      const result = await signInWithPhoneNumber(
        auth,
        formattedPhone,
        verifier
      );

      setConfirmationResult(result);
      setPhoneOtpSent(true);
      setError("");
      console.log("Phone OTP sent successfully");
    } catch (error) {
      console.error("Phone OTP sending error:", error);
      setError(`Failed to send phone OTP: ${error.message}`);
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }
    } finally {
      setLoading(false);
    }
  };

  const verifyPhoneOTP = async () => {
    setError("");
    if (!phoneOtp || phoneOtp.length !== 6) {
      setError("Please enter a valid 6-digit OTP");
      return;
    }

    setLoading(true);
    try {
      await verifyPhoneCode();
      if (window.recaptchaVerifier) {
        window.recaptchaVerifier.clear();
        delete window.recaptchaVerifier;
      }

      const recaptchaContainer = document.getElementById("recaptcha-container");
      if (recaptchaContainer) {
        recaptchaContainer.innerHTML = "";
      }

      setPhoneVerificationSuccess(true);
      setStep(4);
      setShowWebcam(true);
      setError("");
    } catch (error) {
      setError("Invalid phone OTP. Please try again.");
      console.error("Phone OTP verification error:", error);
    } finally {
      setLoading(false);
    }
  };

  const captureFaceImage = () => {
    const imageSrc = webcamRef.current.getScreenshot();
    if (!imageSrc) return;

    // Convert base64 to blob
    fetch(imageSrc)
      .then((res) => res.blob())
      .then((blob) => {
        const file = new File([blob], `face_${Date.now()}.png`, {
          type: "image/png",
        });
        submitVerificationData(file);
      });

    setShowWebcam(false);
    setCaptureSuccess(true);
  };

  const handleFingerprintUpload = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFingerprintImage(file);
    }
  };

  const submitVerificationData = async (faceImageFile) => {
    try {
      const formData = new FormData();
      formData.append("name", name);
      formData.append("aadhaarNumber", aadhaarNumber);
      formData.append("voterId", voterId);
      formData.append("email", email);
      formData.append("phoneNumber", phoneNumber);
      formData.append("phoneOtp", phoneOtp);
      formData.append("faceImage", faceImageFile);

      if (fingerprintImage) {
        formData.append("fingerprintImage", fingerprintImage);
      }

      const response = await axios.post(
        "http://localhost:5000/api/verify-user",
        formData
      );

      if (response.data.success) {
        setCaptureSuccess(true);
        setVerificationSuccess(true);
        setError("");
        setTimeout(() => {
          // Reset form
          setName("");
          setAadhaarNumber("");
          setVoterId("");
          setEmail("");
          setPhoneNumber("");
          setEmailOtp("");
          setPhoneOtp("");
          setEmailOtpSent(false);
          setPhoneOtpSent(false);
          setEmailVerificationSuccess(false);
          setPhoneVerificationSuccess(false);
          setVerificationSuccess(false);
          setCaptureSuccess(false);
          setFingerprintImage(null);
          setStep(1);
          setError("");
          alert("Verification completed successfully! Data saved to database.");
        }, 3000);
      }
    } catch (error) {
      console.error("Submission error:", error);
      if (error.response?.data?.message?.includes("already voted")) {
        setError(`❌ ${error.response.data.message}`);
      } else {
        setError(
          "Failed to submit verification data: " +
            (error.response?.data?.message || error.message)
        );
      }
      setCaptureSuccess(false);
    }
  };

  const handleAadhaarChange = (e) => {
    setAadhaarNumber(e.target.value.replace(/\D/g, "").slice(0, 12));
  };

  const handlePhoneChange = (e) => {
    setPhoneNumber(e.target.value.replace(/\D/g, "").slice(0, 10));
  };

  const handleEmailOtpChange = (e) => {
    setEmailOtp(e.target.value.replace(/\D/g, "").slice(0, 6));
  };

  const handlePhoneOtpChange = (e) => {
    setPhoneOtp(e.target.value.replace(/\D/g, "").slice(0, 6));
  };

  const goToAdminLogin = () => {
    navigate("/admin-login");
  };

  const nextStep = () => {
    if (step === 1 && validateBasicInfo()) {
      setStep(2);
      setError("");
    }
  };

  const prevStep = () => {
    if (step > 1) {
      setStep(step - 1);
      setError("");
    }
  };

  React.useEffect(() => {
    if (captureSuccess) {
      setError("");
    }
  }, [captureSuccess]);

  return (
    <div className="login-background">
      <div className="login-container">
        <div className="user-login">
          <h2>🗳️ E-Voting User Verification</h2>

          {/* Progress Indicator */}
          <div
            className="progress-indicator"
            style={{
              marginBottom: "20px",
              display: "flex",
              justifyContent: "space-between",
              color: "white",
            }}
          >
            <span style={{ fontWeight: step >= 1 ? "bold" : "normal" }}>
              1. Basic Info
            </span>
            <span style={{ fontWeight: step >= 2 ? "bold" : "normal" }}>
              2. Email OTP
            </span>
            <span style={{ fontWeight: step >= 3 ? "bold" : "normal" }}>
              3. Phone OTP
            </span>
            <span style={{ fontWeight: step >= 4 ? "bold" : "normal" }}>
              4. Biometric
            </span>
          </div>

          <div id="recaptcha-container"></div>

          {error && !captureSuccess && (
            <div className="error-message">{error}</div>
          )}

          {verificationSuccess && !showWebcam && !captureSuccess && (
            <div className="success-message">
              OTP Verified! Please complete biometric verification.
            </div>
          )}

          {captureSuccess && (
            <div className="success-message">
              ✅ Verification Complete! Data saved to database.
            </div>
          )}

          {/* Step 1: Basic Information */}
          {step === 1 && (
            <>
              <input
                type="text"
                placeholder="Full Name as per Aadhaar"
                value={name}
                onChange={(e) => setName(e.target.value)}
                className="form-input"
              />

              <input
                type="text"
                placeholder="Aadhaar Number (12 digits)"
                value={aadhaarNumber}
                onChange={handleAadhaarChange}
                className="form-input"
                maxLength="12"
              />

              <input
                type="text"
                placeholder="Voter ID"
                value={voterId}
                onChange={(e) => setVoterId(e.target.value)}
                className="form-input"
              />

              <input
                type="email"
                placeholder="Email Address"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="form-input"
              />

              <button
                onClick={nextStep}
                className="otp-button"
                disabled={loading}
              >
                Next → Email Verification
              </button>
            </>
          )}

          {/* Step 2: Email Verification */}
          {step === 2 && (
            <>
              <div className="success-message">
                ✅ Basic information saved. Please verify your email.
              </div>

              <input
                type="text"
                placeholder="Enter Email OTP (6 digits)"
                value={emailOtp}
                onChange={handleEmailOtpChange}
                className="form-input"
                maxLength="6"
              />

              <div className="button-group">
                <button
                  onClick={verifyEmailOTP}
                  className="verify-button"
                  disabled={loading || !emailOtpSent}
                >
                  {loading ? "Verifying..." : "✅ Verify Email OTP"}
                </button>
                <button
                  onClick={sendEmailOTP}
                  className="resend-button"
                  disabled={loading || emailOtpSent}
                >
                  {emailOtpSent ? "📧 OTP Sent" : "📧 Send Email OTP"}
                </button>
              </div>

              <div className="button-group">
                <button onClick={prevStep} className="resend-button">
                  ← Back
                </button>
              </div>
            </>
          )}

          {/* Step 3: Phone Verification */}
          {step === 3 && (
            <>
              <div className="success-message">
                ✅ Email verified. Please verify your phone number.
              </div>

              <input
                type="text"
                placeholder="Phone Number (10 digits)"
                value={phoneNumber}
                onChange={handlePhoneChange}
                className="form-input"
                maxLength="10"
              />

              {!phoneOtpSent ? (
                <button
                  onClick={sendPhoneOTP}
                  className="otp-button"
                  disabled={loading}
                >
                  {loading ? "Sending OTP..." : "📱 Send Phone OTP"}
                </button>
              ) : (
                <>
                  <input
                    type="text"
                    placeholder="Enter Phone OTP (6 digits)"
                    value={phoneOtp}
                    onChange={handlePhoneOtpChange}
                    className="form-input"
                    maxLength="6"
                  />
                  <div className="button-group">
                    <button
                      onClick={verifyPhoneOTP}
                      className="verify-button"
                      disabled={loading}
                    >
                      {loading ? "Verifying..." : "✅ Verify Phone OTP"}
                    </button>
                    <button
                      onClick={sendPhoneOTP}
                      className="resend-button"
                      disabled={loading}
                    >
                      🔄 Resend OTP
                    </button>
                  </div>
                </>
              )}

              <div className="button-group">
                <button onClick={prevStep} className="resend-button">
                  ← Back
                </button>
              </div>
            </>
          )}

          {/* Step 4: Biometric Verification */}
          {step === 4 && showWebcam && (
            <div className="webcam-section">
              <h3>📷 Face Verification</h3>
              <Webcam
                audio={false}
                ref={webcamRef}
                screenshotFormat="image/png"
                width={320}
                height={240}
                style={{ borderRadius: "8px", border: "2px solid #ddd" }}
              />
              <br />
              <div className="button-group">
                <button onClick={captureFaceImage} className="capture-button">
                  📸 Capture & Verify
                </button>
                <button
                  onClick={() => setShowWebcam(false)}
                  className="resend-button"
                >
                  ❌ Cancel
                </button>
              </div>

              <div
                className="fingerprint-section"
                style={{ marginTop: "20px" }}
              >
                <h4>👆 Fingerprint Upload (Optional)</h4>
                <input
                  type="file"
                  accept="image/*"
                  onChange={handleFingerprintUpload}
                  className="form-input"
                />
              </div>

              <div className="button-group">
                <button onClick={prevStep} className="resend-button">
                  ← Back
                </button>
              </div>
            </div>
          )}

          <div style={{ marginTop: "20px", textAlign: "center" }}>
            <button onClick={goToAdminLogin} className="admin-btn">
              👨‍💼 Admin Login
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
